use vstd::prelude::*;

#[verifier::external_body]
fn rotate_right(list: &Vec<u32>, n: usize) -> Vec<u32> {
    // We know by precondition that list.len() > 0.
    let len = list.len();
    // Compute the effective rotation amount 0 <= m < len.
    let m = n % len;
    // Split point: the suffix starts at index s.
    let s = len - m;

    // Build the rotated vector.
    let mut new_list = Vec::with_capacity(len);
    // First, append the suffix list[s..len].
    for i in s..len {
        new_list.push(list[i]);
    }
    // Then, append the prefix list[0..s].
    for i in 0..s {
        new_list.push(list[i]);
    }

    new_list
}